            ds.totalRevenue += monthlyRevenue;

            ds.competitorUsers = Math.round(ds.competitorUsers * (1 + 0.004 + Math.random() * 0.006));
            var totalMarketUsers = ds.activeUsers + ds.competitorUsers;
            var marketShare = totalMarketUsers > 0 ? (ds.activeUsers / totalMarketUsers) * 100 : 0;

            var ltv = ds.churnRate > 0 ? (d.monthlyPrice * grossMargin * b2bRevenueMultiplier / ds.churnRate) : 0;
            var ltvCacRatio = cac > 0 ? ltv / cac : 0;

            var runway = profit < 0 ? Math.max(0, ds.cash / Math.abs(profit)) : 99;

            ds.lastCac = Math.round(cac * 100) / 100;
            ds.lastLtv = Math.round(ltv);
            ds.lastLtvCacRatio = Math.round(ltvCacRatio * 10) / 10;
            ds.lastRunway = Math.round(runway * 10) / 10;
            ds.lastMarketShare = Math.round(marketShare * 100) / 100;

            ds.mrrHistory.push(Math.round(ds.mrrValue));
            ds.usersHistory.push(ds.activeUsers);
            ds.cashHistory.push(Math.round(ds.cash));
            ds.profitHistory.push(Math.round(profit));

            var avgProfitSoFar = ds.profitHistory.reduce(function(s, p) { return s + p; }, 0) / ds.profitHistory.length;
            var tierScore;
            if (ds.cash <= 0) {
                tierScore = 0;
            } else if (ds.mrrValue > 200000 && ds.lastLtvCacRatio > 3 && avgProfitSoFar > 0) {
                tierScore = 90 + Math.min(10, (ds.mrrValue - 200000) / 20000);
            } else if (ds.mrrValue > 100000 && ds.lastLtvCacRatio > 2) {
                tierScore = 65 + Math.min(20, (ds.mrrValue - 100000) / 100000 * 20);
            } else if (ds.mrrValue > 50000 && avgProfitSoFar > -20000) {
                tierScore = 45 + Math.min(15, (ds.mrrValue - 50000) / 50000 * 15);
            } else {
                tierScore = Math.max(5, Math.min(40, (ds.mrrValue / 50000) * 40));
            }
            var overallScore = Math.max(0, Math.min(100, Math.round(tierScore)));
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: overallScore });
            /* overallScore mirrors the getPerformanceSummary tier waterfall, mrr, ltvCacRatio and avgProfit
               so far mapped through the same 50000, 100000, 200000, 2, 3 thresholds, scaled to 0 to 100 */

            var panel = document.getElementById('resultsPanel');
            if (panel) panel.style.display = 'block';

            // FIX(v1.1.0): advance the market-event briefing synchronously. The
            // previous setTimeout closure read state.currentPeriod AFTER the framework
            // incremented it, so it showed month N+2 — the player was briefed on the
            // wrong month's market event while its demand/cost modifiers silently
            // applied. Guard on state identity so the deep-cloned competition preview
            // never mutates the live DOM.
            if (window.mySimulation && state === window.mySimulation.state) {
                var nextPeriod = (state.currentPeriod || 1) + 1;
                if (nextPeriod <= this.MARKET_EVENTS.length) {
                    this._updateBriefing({ currentPeriod: nextPeriod });
                }
            }

            return {
                period: state.currentPeriod,
                newUsers: newUsers,
                churned: churned,
                activeUsers: ds.activeUsers,
                cac: ds.lastCac,
                churnRate: Math.round(ds.churnRate * 1000) / 10,
                mrr: ds.mrrValue,
                revenue: Math.round(monthlyRevenue),
                costs: Math.round(totalCosts),
                profit: Math.round(profit),
                cash: ds.cash,
                marketShare: ds.lastMarketShare,
                ltv: ds.lastLtv,
                ltvCacRatio: ds.lastLtvCacRatio,
                runway: ds.lastRunway
            };
        }

