        getPerformanceSummary(history) {
            if (!history.length) return {};
            var profits = history.map(function(r) { return r.results ? r.results.profit || 0 : 0; });
            var totalProfit = profits.reduce(function(s, p) { return s + p; }, 0);
            var avgProfit = totalProfit / profits.length;
            var finalMrr = history[history.length - 1].results ? history[history.length - 1].results.mrr || 0 : 0;
            var finalUsers = history[history.length - 1].results ? history[history.length - 1].results.activeUsers || 0 : 0;
            var finalCash = history[history.length - 1].results ? history[history.length - 1].results.cash || 0 : 0;
            var finalLtvCac = history[history.length - 1].results ? history[history.length - 1].results.ltvCacRatio || 0 : 0;

            var performance = 'Struggling Startup';
            var insights = [];

            if (finalCash <= 0) {
                performance = 'Bankrupt';
                insights.push('The startup ran out of cash. Cash management and burn rate control are critical for survival.');
            } else if (finalMrr > 200000 && finalLtvCac > 3 && avgProfit > 0) {
                performance = 'Unicorn Potential';
                insights.push('Outstanding execution with strong unit economics and rapid growth.');
                insights.push('With an LTV/CAC ratio above 3x and positive margins, this startup is investor-ready.');
            } else if (finalMrr > 100000 && finalLtvCac > 2) {
                performance = 'Growth Stage Ready';
                insights.push('Solid growth trajectory with healthy unit economics.');
                insights.push('Consider optimizing channel mix to further improve CAC efficiency.');
            } else if (finalMrr > 50000 && avgProfit > -20000) {
                performance = 'Finding Product-Market Fit';
                insights.push('The startup is gaining traction but unit economics need improvement.');
                insights.push('Focus on reducing churn and improving retention to increase LTV.');
            } else {
                insights.push('Growth was slower than expected. Review channel strategy and pricing.');
                insights.push('Consider whether the target segment and pricing model are aligned.');
            }

            return {
                totalProfit: Math.round(totalProfit),
                averageMonthlyProfit: Math.round(avgProfit),
                finalMrr: Math.round(finalMrr),
                finalActiveUsers: finalUsers,
                cashRemaining: Math.round(finalCash),
                finalLtvCacRatio: finalLtvCac,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.cash <= 0) {
                return window.mySimulation.t('hint_bankrupt');
            }
            if (results.runway < 4 && results.runway < 99) {
                return window.mySimulation.t('hint_low_runway');
            }
            if (results.ltvCacRatio < 1.5 && results.ltvCacRatio > 0) {
                return window.mySimulation.t('hint_low_ltv_cac');
            }
            if (results.churnRate > 10) {
                return window.mySimulation.t('hint_high_churn');
            }
            if (results.profit > 0 && results.mrr > 50000) {
                return window.mySimulation.t('hint_strong');
            }
            if (results.newUsers < 500 && state.currentPeriod > 3) {
                return window.mySimulation.t('hint_slow_growth');
            }
            return null;
        }

